#!/usr/bin/env bash
set -Eeuo pipefail
B="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"; cd "$B"; port=${TF_FRONTEND_PORT:-$([[ ${OPERACIONES_GLOBAL:-0} == 1 ]] && echo 18111 || echo 8111)}; vars=(-var="frontend_port=$port" -var="postgres_password=devops123" -var="backend_image=operaciones1-guia11-backend:local" -var="frontend_image=operaciones1-guia11-frontend:local")
case ${1:-} in iniciar) docker build --provenance=false -t operaciones1-guia11-backend:local backend; docker build --provenance=false -t operaciones1-guia11-frontend:local frontend; terraform init -input=false; terraform apply -auto-approve -input=false "${vars[@]}";; detener) echo 'Se destruirán únicamente recursos TP11 gestionados por este state.'; terraform destroy -auto-approve -input=false "${vars[@]}";; reiniciar) "$B/operaciones.sh" detener; "$B/operaciones.sh" iniciar;; estado) terraform output; docker ps --filter label=managed-by=terraform;; verificar) terraform fmt -check -recursive; terraform init -input=false; terraform validate; terraform plan -input=false "${vars[@]}" >/dev/null; if docker ps --filter label=managed-by=terraform --filter status=running --format '{{.Names}}' | grep -q .; then for _ in $(seq 1 30); do curl -fsS "http://127.0.0.1:$port/health" | jq -e '.status=="ok"' >/dev/null && exit 0; sleep 1; done; echo 'fmt/validate/plan OK, pero la infraestructura aplicada no responde en /health.' >&2; exit 1; else echo 'fmt/validate/plan OK. No hay infraestructura aplicada todavia (correr: ./operaciones.sh iniciar) -- verificar no construye imagenes ni hace terraform apply.'; fi;; logs) docker logs "$(docker ps --filter label=managed-by=terraform --filter label=replica=0 --format '{{.Names}}' | head -1)" --tail=100 2>/dev/null || terraform show;; *) exit 64;; esac
